const i = $input.first();
const j = i.json;
const p = j.payload || j;
const mode = p.mode || j.transcription_mode || 'production';
const provider = p.provider || j.transcription_provider || null;
const model = p.model || j.transcription_model || null;
const allowed = new Set(['openai:gpt-transcribe', 'gemini:gemini-3.5-transcribe']);

if (mode === 'production' && (!provider || !model)) {
  throw new Error('TRANSCRIPTION_PRIMARY_NOT_SELECTED: run approved benchmark before production routing (AI-DEC-007)');
}

if (!provider || !model || !allowed.has(`${provider}:${model}`)) {
  throw new Error('TRANSCRIPTION_PROVIDER_MODEL_NOT_APPROVED: provider and model must match approved registry');
}

return [{
  json: {
    ...j,
    transcription_mode: mode,
    transcription_provider: provider,
    transcription_model: model
  },
  binary: i.binary
}];

