const j = $input.first().json;
const ctx = $('Validate Transcription Contract').first().json;
const text = j.text || j.transcript || j.candidates?.[0]?.content?.parts?.[0]?.text || j.output_text || j.output?.text || null;
if (!text || !String(text).trim()) {
  throw new Error('EMPTY_TRANSCRIPTION: provider returned empty transcript');
}

const inputTokens = j.usage?.prompt_tokens ?? j.usageMetadata?.promptTokenCount ?? null;
const outputTokens = j.usage?.completion_tokens ?? j.usageMetadata?.candidatesTokenCount ?? null;
const reqId = j.id || j.responseId || null;
const durationMs = ctx.payload?.duration_ms || ctx.duration_ms || null;
const audioSec = durationMs ? Number((durationMs / 1000).toFixed(2)) : (j.duration ? Number(j.duration) : null);

return [{
  json: {
    ...ctx,
    transcript_text: String(text).trim(),
    transcript_language: j.language || 'es-AR',
    provider_request_id: reqId,
    input_tokens: inputTokens,
    output_tokens: outputTokens,
    audio_seconds: audioSec,
    estimated_cost_usd: null,
    pricing_version: null,
    raw_provider_metadata: {
      has_segments: Array.isArray(j.segments),
      has_words: Array.isArray(j.words)
    }
  }
}];

const norm = $('Normalize Transcription Output').first().json;
const sourceRes = $('Persist Literal Transcription').first().json.res;
const stId = sourceRes.source_text_id || (typeof sourceRes === 'string' ? JSON.parse(sourceRes).source_text_id : null);
const usageId = $('Record Transcription AI Usage').first().json.id;

return [{
  json: {
    ok: true,
    status: 'completed',
    ingestion_id: norm.ingestion_id,
    asset_id: norm.asset_id,
    source_text_id: stId,
    transcript_text: norm.transcript_text,
    provider: norm.transcription_provider,
    model: norm.transcription_model,
    usage_id: usageId
  }
}];
